DROP TABLE IF EXISTS `asistati_social`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `asistati_social` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nume` text NOT NULL,
  `prenume` text NOT NULL,
  `cnp` varchar(20) NOT NULL,
  `serie_nr_ci` varchar(50) NOT NULL,
  `adresa_completa` varchar(1000) NOT NULL,
  `localitate` text NOT NULL,
  `judet` text NOT NULL,
  `stare_civila` text NOT NULL,
  `nr_copii` int(11) NOT NULL,
  `descriere` varchar(5000) NOT NULL,
  `descriere_scurta` varchar(500) NOT NULL,
  `contract_sponsorizare` text NOT NULL,
  `link_contract` varchar(500) NOT NULL,
  `link_ci` varchar(200) NOT NULL,
  `telefon` varchar(20) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=93 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
