INSERT INTO `asistati_social` VALUES (1,'Cojocaru','Ionel-Sterian','1810511170089','ZL349426','Str. George Enescu nr. 11A, Galați, jud. Galați','Galați','Galați','Necăsătorit',0,'&lt;p&gt;&lt;strong&gt;Bolnav&lt;/strong&gt;, locuiește cu mama bolnavă. Muncește cu ziua pe unde poate. Se află &amp;icirc;n evidența Bisericii Greacă din Galați la pr. Ionel Panait. Este un băiat harnic și cinstit.&lt;/p&gt;','','nu','','asistati-social\\Cojocaru-Ionel-Sterian\\copie-ci-cojocaru-ionel-sterian.jpg',''),(2,'Olteanu','Dorina','2880717170110','GL874281','Str. Filești nr.3, Galați, jud. Galați','Galați','Galați','Văduvă',2,'&lt;p&gt;Soțul este șofer pe tir și a murit &amp;icirc;ntr-un accident de mașină &amp;icirc;n Germania. Doamna a rămas văduvă cu 2 copii și locuiește &amp;icirc;ntr-o casă fără autorizație de construcție pe malul r&amp;acirc;ului din Filești. &lt;/p&gt;\r\n&lt;p&gt;Nu are servici, se descurcă greu cu banii.&lt;/p&gt;','','nu','','asistati-social\\Olteanu-Dorina\\copie-ci-olteanu-dorina.jpeg',''),(24,'Marin','Rodica','2830521170074','PA159556','Strada aviator Mircea Zorileanu nr. 8, bl. S1, ap.3 jud. Galați','Galați','Galați','Necăsătorită',7,'&lt;p&gt;Doamna Rodica Marin are 7 copii pe care &amp;icirc;i crește fără soț. Se descurcă greu.&lt;/p&gt;','','nu','','',''),(23,'Radu','Mihai','1840508170095','PA558210','strada Alexandru Vlahuță nr. 4  jud. Galați','Cartierul Filești, Galați','Galați','Necăsătorit',2,'','','nu','','','0740346274'),(37,'Cruceanu','Vlad','1871105170047','RK267177','Str. Vâlsănești nr.7, Sector 3, București','București','București','Necăsătorit',0,'&lt;p&gt;Orfan care a stat ani de zile pe stradă. &lt;/p&gt;','','nu','','asistati-social/Cruceanu-Vlad/copie-ci-Vlad-Cruceanu.jpeg',''),(25,'Constantin','Lidia','2510823170390','GL346437','Strada Cluj nr. 11, bl. D5A, ap. 21, Galați. jud. Galați','Galați','Galați','Văduvă',0,'&lt;p&gt;Văduvă pensionară care locuiește &amp;icirc;ntr-o sărăcie cruntă la bloc, fără căldură, fără apă caldă, și are &amp;icirc;n &amp;icirc;ntreținere pe fiul ei bolnav care nu muncește.&lt;/p&gt;\r\n&lt;p&gt;Doamna Lidia are și pensie și lucrează &amp;icirc;n același timp.&lt;/p&gt;','','nu','','',''),(36,'Dănilă','Giani Ionuț','1890425171716','GL 943250','Strada Laminoriștilor nr. 7, bl. T2, ap.14, Galați, jud. Galați','Galați','Galați','Căsătorit',0,'&lt;p&gt;Persoană cu handicap căsătorit cu o femeie cu handicap. Nu lucrează, au venituri mici.&lt;/p&gt;','','nu','','',''),(38,'Iordache','Eliza-Gabriela','266102017034','GL998627','Strada Vegetalelor nr. 2. Galați, jud. Galați','Galați','Galați','Divorțată',2,'&lt;p&gt;Divorțată, fără venituri.&lt;/p&gt;','','nu','','',''),(40,'Stan','Caterina','2810405100145','XZ627206','Str. Independenței nr. 4, Buzău, jud. Buzău','Buzău','Buzău','Căsătorită',5,'&lt;p&gt;Femeie necăjită cu soțul bolnav și 5 copii.&lt;/p&gt;','','nu','','',''),(41,'Andrei','Sebastian','1780429174891','PA160847','Str. Victor Papilian nr.7, bl. H1, ap.21, Galați, jud. Galați','Galați','Galați','Necăsătorit',7,'&lt;p&gt;Trăiește cu doamna Ionela. Cresc &amp;icirc;mpreună 7 copii, dintre care unul bolnav de cancer. Au venituri mici.&lt;/p&gt;','','nu','','',''),(43,'Șuia','Constanța','269013037346','VS516346','Sat Vulturești jud. Vaslui','Vulturești','Vaslui','Divorțată',0,'','','nu','','',''),(44,'Precupețu','Doru','1740927170331','GL964286','Strada Narciselor  nr. 42, Galați, jud. Galați','Galați','Galați','Căsătorit',0,'&lt;p&gt;Persoană cu handicap.&lt;/p&gt;\r\n&lt;p&gt;Decedat.&lt;/p&gt;','','nu','','',''),(45,'Călămuz','Ileana','2670823174932','PA159556','Str. Laminoriştilor nr. 6, bl. G2, ap.116, Galați, jud. Galați','Galați','Galați','Necăsătorită',0,'','','nu','','',''),(49,'Precupețu','Ileana Oana','2760119170391','ZL221741','Str. Drumul de Centură, r. 39F, bl. M4, ap. 16, Galați, jud. Galați','Galați','Galați','Văduvă',0,'&lt;p&gt;Văduvă, șomeră, are probleme cu un picior.&lt;/p&gt;','','nu','','',''),(50,'Doroșenco','Mirabela','','','','Galați','Galați','Căsătorită',1,'&lt;div data-pm-slice=&quot;1 1 []&quot; data-en-clipboard=&quot;true&quot;&gt;Operată pe creier.&lt;/div&gt;','','nu','','','0757 767 935'),(52,'Prisecaru','Valentin','1911113171708','955823','Str. Zimbrului nr.5, Galați, jud. Galați','Galați','Galați','Necăsătorit',0,'&lt;p&gt;A crescut &amp;icirc;n orfelinat.&lt;/p&gt;','','nu','','asistati-social/Prisecaru-Valentin/Prisecaru Valentin-Adrian-copie-ci.jpeg','0758283251'),(53,'Enculescu','Nicoleta','2720812463053','RK556296','Strada Calugareni, nr.3, sector 3, București','București','București','Necăsătorită',0,'&lt;p&gt;Profesoară &amp;icirc;n București&lt;/p&gt;','','nu','','','0746398753'),(54,'Gașpar','Claudia-Elisabeta','2850311115196','RK192923','Drumul Taberei nr. 85A, bl. TS7, sc.1, et. 7, ap. 43','București','București','Divorțată',1,'','','nu','','asistati-social/Gaspar-Claudia-Elisabeta/Gaspar-Claudia-Elisabeta-copie-ci.jpeg','0787236322'),(55,'Balan','Claudiu','1830620170030','GL718081','Str: Frunzei nr. 5, bl. F3, sc.2, ap. 63, Galați, jud. Galați','Galați','Galați','Căsătorit',3,'','','nu','','asistati-social/Claudiu-Balan/Claudiu Balan - copie BI.jpg','0740004215'),(56,'Lupu','Marinela','2950421046211','ZH215209','Sat Popești, comuna Popești nr. 87C','Bacău','Bacău','Căsătorită',2,'&lt;p&gt;Se află &amp;icirc;n Birmingham Anglia și nu are bani să vină acasă. Nu mai are bani de chirie.&lt;/p&gt;','','da','','asistati-social/Lupu-Marinela/Lupu-Marinela-copie-ci.jpeg','+447723624709'),(57,'Stratu','Georgiana-Rodica','2940725170042','GL973999','Str. Feroviarilor nr. 15, bl. C8, sc. 5, et. 2, ap. 111, Galați, jud. Galați','Galați','Galați','Necăsătorită',0,'&lt;p&gt;O fosta jucătoare de fotbal din liga I, din Galați, care a avut un accident la genunchi cu ceva ani &amp;icirc;n urma și de atunci patimeste cu operații peste operații și dureri greu de suportat. Are 26 de ani, și doar un frate mai mic, și el destul de bolnav, și fizic nu poate face multe in perioada asta din cauza durerilor. Locuiește singura.&lt;/p&gt;\r\n&lt;p&gt;Cineva ar putea sa ii faca o vizita și sa ii ducă o m&amp;acirc;ncare gătită, sau sa o ajute cu cumpărăturile, sa stea puțin de vorba sa o mai &amp;icirc;ncurajeze și sa o bucure puțin, sa mai uite de durerea ei. Sau poate cineva sa o ajute cu mașina sa meargă la o Liturghie, sau poate sa o scoată un pic din casa la o plimbare scurta dacă sănătatea ii permite. Cineva care sa mai tina legatura cu ea și c&amp;acirc;nd nu are ce pune pe masa sa ii ducă o farfurie de ceva.&lt;/p&gt;','','da','','asistati-social/Stratu-Georgiana-Rodica/Georgiana-Stratu.jpeg','0753 898 287'),(58,'Boza','Costel','1990525172363','ZL136802','Sat Vîrlezi (Com. Vîrlezi)','Vîrlezi','Galați','Căsătorit',2,'&lt;p&gt;Familie necăjită din județul Galați. cu 2 copii, care nu au casă, nu au venituri, trăiesc din agricultură.&lt;/p&gt;','','da','','asistati-social/Boza-Costel/Costel-Boza-copie-ci.jpg','0755667726'),(60,'Dl','Ion','','','Biserica Sf. Andrei','Galati','Galati','Căsătorit',0,'&lt;p&gt;Un bărbat &amp;icirc;n v&amp;acirc;rstă de aproximativ 50 de ani. Merge șchiop, &amp;icirc;mbrăcat foarte modest, lucrează &amp;icirc;n Piața din Micro 17 la sacii cu cartofi.&lt;/p&gt;','','da','','',''),(61,'Sefer','Nicoleta','2840721170088','PA896864','Str. Aviator Mircea Zorileanu nr. 5 bl. I1 sc.4, ap.70','Galați','Galați','necasatorit',5,'<p>Locuiește &icirc;n satul Filești &icirc;ntr-o casă foarte sărăcăcioasă, complet fără utilități. Soțul a părăsit-o. Nu are venituri.</p>','familie cu 3 copiii în întreținere, fără venituri','da','','','0757450717'),(62,'Grigorache','Dorin','1821113170097','GL826404','Str. Berlin nr.25, bl. S2, sc.1, ap.5','Galați','Galați','Căsătorit',0,'&lt;p&gt;Casătorit cu Dana Grigorache. Stau &amp;icirc;n cartierul Dimitrie Cantemir ANL. Nu au servicii. Soțul are insuficiență renală și face dializă.&lt;/p&gt;','','da','','',''),(63,'Dima','Gabriel Nicolae','1690322164005','KZ654985','Str. Silozului, Pavilion CFR nr.2','Medgidia','Constanța','Căsătorit',2,'&lt;p&gt;Familie necăjită din Medgidia. Soțul are handicap la ochi. Au 2 copii.&lt;/p&gt;','','da','','',''),(64,'Pelipenco','Geanin','1830101170000','GL00000','Str. Tecuci nr. 91','Galați','Galați','Necăsătorit',0,'&lt;div data-pm-slice=&quot;1 1 []&quot; data-en-clipboard=&quot;true&quot;&gt;Pareza spastica. Merge in carje și nu are venituri. Cerșește la Biserica Sf. Vasile din Galați. Caută uneori și prin gunoaie.&lt;/div&gt;','','da','','',''),(65,'Dulici','Florinița','2790319513498','KL493990','Str. Călărași nr. 93','Sat Răzvani, Oraș Lehliu-Gară','Călărași','Căsătorită',3,'','','da','','asistati-social/Dulici-Florinita/Dulici-Florinita-copie-bi.jpg',''),(66,'Videnie','Nicolae','','','','București','București','Necăsătorit',0,'&lt;p&gt;Un profesor singur, care trăiește fără venituri &amp;icirc;ntr-un apartament destinat Centrului de Istorie Recentă din București de pe Bulevardul Magheru. Telefon: 0724803577&lt;/p&gt;','','da','','',''),(67,'Radu','Ionuț','1950511170088','ZL321445','Str. Ștefan cel Mare nr. 30B, sat Brașniștea (com. Braniștea), jud. Galați','Brașniștea','Galați','Necăsătorit',0,'&lt;p&gt;Fost copil orfan care a stat &amp;icirc;n centrul de plasament de pe strada Radu Negru din Galați. Muncește momentan și &amp;icirc;ncearcă să-și construiască o casă. A dob&amp;acirc;ndit de la Primăria Braniștea un teren unde vrea să construiască o casă. Caută peste ajutor să &amp;icirc;nceapă construcția casei ca să nu piardă terenul. Momentan sta &amp;icirc;n chirie.&lt;/p&gt;','','da','','asistati-social/Radu-Ionut/Radu Ionut  copie ci.jpeg','0759696653'),(68,'Ciobotaru','Mihaela','2801029170090','ZL345499','Str. Drumul de Centura nr. 390, bl. M12, ap. 14','Galati','Galati','Divorțată',6,'&lt;p&gt;Divortata cu 6 copii. Locuieste intr-un apartament social al Primariei Galati care e foarte mic si ne&amp;icirc;ncăpător. Lucrează la Spitalul Județean Galați ca &amp;icirc;ngrijitoare.&lt;/p&gt;\r\n&lt;p&gt;E căsătorită cu 2 copii și se descurcă greu cu banii. Acum nu mai muncește. Doar soțul &amp;icirc;ntreține familia.&lt;/p&gt;','','da','','','0756 990 866'),(69,'Ursu','Georgiana','2910618375504','VS718586','Sat Alexandru Vlahuță, comuna Alexandru Vlahuță, jud. Vaslui','Sat Alexandru Vlahuță','Vaslui','Necăsătorită',3,'&lt;p&gt;Georgiana Ursu locuiește &amp;icirc;n satul Buturugeni, jud. Giurgiu singură cu cei 3 copii, fără venituri. Nu a fost căsătorită. Barbatul o ajută c&amp;acirc;nd și c&amp;acirc;nd...&lt;/p&gt;','','da','','asistati-social/Ursu-Georgiana/WhatsApp Image 2021-12-21 at 11.39.32.jpeg','0767780826'),(70,'Mușet','Zina','2710912174898','ZL 326959','Str. Drumul de Centura nr. 39F, bl. M4, ap. 17','Galați','Galati','Căsătorită',0,'&lt;p&gt;tumoare malignă la s&amp;acirc;n&lt;/p&gt;','','da','','asistati-social/Muset-Zina/copie-bi-Muset-Zina.jpg','0744358722'),(71,'Dobrea','Mariana','2710329433017','RK484906','Str. Hășmaș nr. 35, sectorul 3, București','București','București','Necăsătorită',0,'&lt;p&gt;&quot;Oameni cu suflet bun, sunt Dobre Mariana,&amp;nbsp; o fata singura, pensionata medical cu gradul doi și cu handicap accentuat . Va rog mult sa ma ajutati cu 7000 lei sau c&amp;acirc;t puteți, necesari pentru o &lt;strong&gt;artroscopie grad doi la genunchiul drept&lt;/strong&gt;, deoarece am fisuri de menisc, gonartroza incipienta și o bucata de cartilagiu de cca 1 cm rupta din el și acesta poate sa imi distrugă oricand restul de cartilagiu rămas și sa &amp;icirc;mi blocheze piciorul, dacă ajung prea t&amp;acirc;rziu la operație. Ma trag din bulgari, tata era din Vadul Anei si un strabunic din partea lui a fost dat dispărut &amp;icirc;n Rusia. Am operații și de hernie lombara și de hernie cervicala din 2019 și am pareza pe piciorul drept și semipareza pe mana dreaptă.&amp;nbsp; Am ajuns prea t&amp;acirc;rziu la operații. Am lucrat &amp;icirc;n mediu toxic și nu am simțit durerea. Am 51 % capacitate&amp;nbsp; de a mi menține echilibrul.&amp;nbsp; Ca sa pot sa merg si sa nu am dureri mari, fac injectii cu diclofenac, pentru ca ma doare fierea sau ficatul de la pastile antiinflamatoare, și fac gimnastica &amp;icirc;n fiecare zi.&quot;&lt;br /&gt;&lt;br /&gt;Acum din cauza genunchiului nu mai pot sa fac exercițiile pentru coloana lombara și merg din ce &amp;icirc;n ce mai greu. Menționez ca sunt o fata credincioasa care nu m-am putut căsători, deși mi am dorit, pt ca am &amp;icirc;ncercat sa fie căsătorie binecuv&amp;acirc;ntată de Dumnezeu,&amp;nbsp; nu sa ma duc cu cineva &amp;icirc;n concediu&amp;nbsp; după prima &amp;icirc;nt&amp;acirc;lnire,&amp;nbsp; cum mi a zis mama sau pentru ca mi s-a cerut sa plec din casa, și sa o las singura pe mama. Dacă am greșit numai Dumnezeu știe. C&amp;acirc;nd aveam opt ani, tata a paralizat pe partea dreaptă, deoarece a avut o tumora cerebrală și mama &amp;icirc;mi cerea ca &amp;icirc;l ridic din pat, și am avut grija și de mama. Am fost odată la Părintele Justin Parvul și a zis ca este mucenicie fără s&amp;acirc;nge și ca sunt blesteme ale bunicilor. Dumnezeu sa va binecuvinteze și va dea ce va este de folos tuturor care ma ajutați.&lt;/p&gt;','','da','','asistati-social/Dobrea-Mariana/Dobre-Mariana-ci.jpeg','+40 720 351 488'),(72,'Parfeni','Tincuța','2781028170345','ZL478965','Str. Ghecet nr. 13','Galați','Galați','Căsătorită',10,'&lt;p&gt;Vreau sa va mai scriu despre o familie cu 10 copiii cei mai mici cu v&amp;acirc;rsta de: 1 an, 3 ani,8 ani, 11 ani, 14 ani, 17 ani și 18 ani. Aceasta familie trăieste din ajutorul social de la Primărie, cantina, alocatiile copiilor și pensia de handicap a soțului.&lt;/p&gt;\r\n&lt;p&gt;Menționez ca, sotul este pensionat pe caz de boala av&amp;acirc;nd&amp;nbsp; carcasa metalica montata la nivelul capului .&lt;br /&gt;Aceasta familie a locuit multi ani &amp;icirc;n chirie la casele muncii &amp;icirc;nsă au fost dați afară de acolo și au fost nevoiți sa caute un spațiu de locuit iar singurul loc unde sa poată fi acceptata o familie cu 2 adulti și 7 copiii deoarece ceilalți 3 copiii din cei 10 sunt adulti si numai locuiesc cu părinții.&lt;/p&gt;\r\n&lt;p&gt;&amp;Icirc;n acest moment locuiesc intr-o casa situata pe strada Ghecet nr.13 &amp;icirc;nsă aceasta casa este improprie de a locui &amp;icirc;n ea deoarece prezintă fisuri &amp;icirc;n tavan, miros și prezenta de mucegai precum și prezenta de igrasie, acestea prezent&amp;acirc;nd un risc de &amp;icirc;mbolnăvire atat &amp;icirc;n r&amp;acirc;ndul copiilor c&amp;acirc;t și a părinților.&lt;/p&gt;\r\n&lt;p&gt;Va atașez poze sa puteți vedea condițiile de locuit și v-as fi veșnic recunoscătoare dacă i-ati putea ajuta cu o locuință și cele necesare traiului zilnic.&lt;/p&gt;\r\n&lt;p&gt;Va aduc la cunoștință faptul ca, aceasta familie risca sa răm&amp;acirc;nă &amp;icirc;n strada &amp;icirc;n toiul iernii deoarece doamna la care stau &amp;icirc;n chirie vrea sa elibereze spațiul.&lt;/p&gt;\r\n&lt;p&gt;Numărul de telefon a mamei este: 0746341205 se numește Tincuta.&lt;/p&gt;','','da','','asistati-social/Parfeni-Tincuta/Parfeni-Tincuța.jpeg','0746341205'),(73,'Cosencu','Gherghina','2461024361932','ZL469899','Str. Tomis, nr. 19A','Sat Grindu, Comuna Grindu','Tulcea','Văduvă',0,'&lt;p&gt;Dragilor, vă cerem iarăși ajutorul pentru o bătr&amp;acirc;nică care locuiește &amp;icirc;ntr-o casă veche și puternic deteriorată, și &amp;icirc;n condiții mizere &amp;icirc;n frig și multă sărăcie. &lt;strong&gt;Doamna Gherghina Cosencu are 76 de ani și este de 5 ani de zile nevăzătoare,&lt;/strong&gt; locuind &amp;icirc;n cartierul Filești de la marginea municipiului Galați. Primește de la cineva din familie m&amp;acirc;ncare &amp;icirc;n fiecare zi dar are nevoie mare de un nouă căsuță. &amp;Icirc;ncercăm, cu ajutorul lui Dumnezeu să-i ajutăm pe cei din familia ei să-i construiască o mică căsuță de o cameră. Casa actuală se dăr&amp;acirc;mă la propriu peste ea.&lt;/p&gt;\r\n&lt;p&gt;Familia are deja str&amp;acirc;nsă o mică sumă de bani și vrem să mai contribuim și noi cu &lt;strong&gt;10.000 de lei pentru ridicarea unei mici construcții. &lt;br /&gt;&lt;/strong&gt;Camera va avea 6x4 m și va avea o mică fundație, panouri sandviș ca pereți, și un acoperiș.&lt;/p&gt;\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;','','da','','asistati-social/Cosencu-Gherghina/Gherghina Cosencu (3).jpeg','+40 754 846 822'),(74,'Parfeni','Eduarda Elisabeta','6031117170035','Pasaport 062024458','','Galați','Galați','Necăsătorită',0,'&lt;p&gt;Este una din fetele doamnei Parfeni Tincuța cu 10 copii.&lt;/p&gt;','','da','','asistati-social/Parfeni-Eduarda Elisabeta/Parfeni-Eduarda-Elisabeta.jpg','+40759871627'),(75,'Ciuca','Andreea Mădălina','2910910385594','VX 659082','Aleea Ciocârliei nr. 1 bl. 6 sc. C, ap.10','Râmnicu Vâlcea','Vâlcea','Necăsătorită',0,'&lt;p&gt;Doamna Ciuca Andreea Mădălina, &amp;icirc;n v&amp;acirc;rstă de 31 de ani, are lombosciatalgie și parestezii dureroase S1 st&amp;acirc;nga remarcată din luna decembrie a anului 2022, pentru care a efectual IRM coloana lombo-sacrata cu contrast, care a pus &amp;icirc;n evidență tumora sacrala, cu extensie presacrală st&amp;acirc;nga și la nivelul musculaturii paravertebrale sacrate, ce cuprinde rădăcinile S1, S2 și S3 și afectează parțial osul, &amp;icirc;nsă nu afectează stabilitatea coloanei vertebrale, aspect sugestiv pentru sarcom, conform descrierii medicului radiolog. Relatează ameliorarea simptomatologiei algo-parestezice după administrare de gabaran și medrom 32 mg.&lt;/p&gt;','','da','','asistati-social/Ciuca-Andreea Madalina/Ciuca-Andreea-Madalina-CI.jpg','+40 729 119 049 (Ale'),(76,'Ionescu','Călin','1830810170104','GL986807','Str. Grigore Ventura nr. 5, bl. J11, sc.4, ap. 60','Galați','Galați','Căsătorit',7,'&lt;p&gt;&lt;!-- [if gte mso 9]&gt;&lt;xml&gt;\r\n &lt;o:OfficeDocumentSettings&gt;\r\n  &lt;o:AllowPNG/&gt;\r\n &lt;/o:OfficeDocumentSettings&gt;\r\n&lt;/xml&gt;&lt;![endif]--&gt;Cu bucurie &amp;icirc;n suflet vă scriu o mică prezentare a familiei noastre. Noi, Elena și Călin Ionescu suntem binecuv&amp;acirc;ntații părinți a șapte copilași&lt;span lang=&quot;EN-US&quot; style=&quot;mso-ansi-language: EN-US;&quot;&gt;: David (16 ani), Stelian (13 ani), Andrei (11 ani), Maria (9 ani), Alexandru (7 ani), Teodora (4 ani) &lt;/span&gt;și&lt;span lang=&quot;EN-US&quot; style=&quot;mso-ansi-language: EN-US;&quot;&gt; mezinul Matei (1 an).&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;MsoNormal&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;mso-ansi-language: EN-US;&quot;&gt;Cu mare recunoștință am primit fiecare copilaș trimis de Bunul Dumnezeu, iar eu nu am putut munci deoarece mă ocup, &amp;icirc;n special, de creșterea și educația lor. Soțul este gestionar la un service auto și este singura sursă de venit. Nu am reușit să investim &amp;icirc;ntr-o locuință, așadar stăm cu chirie care este 250 euro. Datorită sponsorizării primite am reușit să ducem copiii la activitățile preferate: &lt;/span&gt;&amp;icirc;not, fotbal, handbal, baschet, pian (fiecare cu &amp;icirc;nclinația sa).&lt;/p&gt;\r\n&lt;p class=&quot;MsoNormal&quot; style=&quot;text-align: justify;&quot;&gt;Viața cu șapte copii este minunată, nu este ușoară, &amp;icirc;nsă inocența celor mici molipsește &amp;icirc;ntreaga casă și la noi este o continuă bucurie.&lt;/p&gt;\r\n&lt;p class=&quot;MsoNormal&quot; style=&quot;text-align: justify;&quot;&gt;Nevoile sunt mari dar și purtarea de grijă a Domnului este nemărginită, trebuie doar ne &amp;icirc;ncredem &amp;icirc;n poruncile Lui și să avem nădejde.&lt;/p&gt;\r\n&lt;p class=&quot;MsoNormal&quot; style=&quot;text-align: justify;&quot;&gt;Nu putem dec&amp;acirc;t să dăm slavă Domnului pentru toate și să ne lăsăm &amp;icirc;n Voia Sa.&lt;/p&gt;\r\n&lt;p class=&quot;MsoNormal&quot; style=&quot;text-align: justify;&quot;&gt;Amin!&lt;/p&gt;\r\n&lt;p class=&quot;MsoNormal&quot;&gt;Cu recunoștință,&lt;/p&gt;\r\n&lt;p class=&quot;MsoNormal&quot;&gt;Fam. Ionescu&lt;/p&gt;','','da','','asistati-social/Ionescu-Calin/Ionescu-Calin-copie-bi.jpg','+40741046501'),(77,'Tudor','Liliana','2891230170076','ZL001429','Str. Alexandru Moruzzi nr. 80','Galați','Galați','Căsătorită',0,'&lt;p&gt;Acum va scriu in speranța ca ma puteti ajuta si pe mine, problemele mele de sănătate au &amp;icirc;nceput in iulie 2021. In urma unei testari Papanicolau, a unei genotipari HPV si a unei colposcopii am iesit suspecta de displazie moderata de col uterin, pozitiv HPV 70, un virus nemilos, care mi a si provocat leziunea.&lt;/p&gt;\r\n&lt;p&gt;In noiembrie 2021 am fost supusa unei intervenții chirurgicale, mai precis a unei conizatii. Am apelat la regim privat in ideea ca sunt tanara si in urma mai multor recomandari am ajuns la Regina Maria la Prof Dr Bratila Petre care mi a efectuat intervenția. 10.000 de lei a ajuns intervenția cu analizale premergătoare operatiei, după intervenție am efectuat controale periodice din 3 in 3 luni, colposcopii, tratamente pentru imunitate deoarece nu a fost de ajuns doar intervenția atat timp cat exista virusul in organism.&lt;/p&gt;\r\n&lt;p&gt;Toate bune pana in iulie anul acesta cand am avut un rezultat pozitiv la testarea Papanicolau si colposcopie fapt care a indicat prezenta unei noi leziuni, am ajuns la Regina Maria, mi s a recomandat o a doua intervenție chirurgicala, am fost nevoita sa fac credit la Provident si sa ma &amp;icirc;mprumut de unde am putut inclusiv de la serviciu:&lt;/p&gt;\r\n&lt;p&gt;Nu sunt un om care sa aștept ceva de la cineva gratis, sunt mama a unei fetite de 8 ani, lucrez, dar nu mai pot financiar, am datorii pe care nu mai stiu cum sa le platesc. Am 10 zile de la operație, am de facut iar drumuri la București, controale, tratamente pentru imunitate, de facut cu Isoprinosine 6cps/zi ,10 zile pe luna timp de 6 luni, 80 lei cutia care nu acoperă tratamentul pentru 1 luna,Coriolus Mrl 6 cps /zi o cutie costa 125 de lei si acoperă tratamentul pentru 15 zile, Ahcc care costa 260 lei cutia, vitamine care imi sunt necesare pentru a lupta cu virusul HPV.&lt;br /&gt;&lt;br /&gt;Nu mai stiu ce sa fac,aștept rezultatul biopsiei si &amp;icirc;mi este teamă de ce va urma,nu mai stiu incotro sa o iau.&lt;/p&gt;','','da','','asistati-social/Tudor-Liliana/Tudor Liliana.jpg','+40747455552'),(78,'Ivanciu','Loredana-Daniela','2880622204515','ZL301420','Str. Gheorghe Stroiciu nr. 6','Galați','Galați','Necăsătorită',1,'&lt;p&gt;O femeie de 35 de ani are nevoie de ajutor este o mama cu un copil de 10 ani abia diagnosticata cu cancer limfatic-limfom Hodgkin, nu are bani pentru transport și m&amp;acirc;ncare pentru a ajunge la Iași unde este programata luni pentru &amp;icirc;nceperea tratamentului. Se afla internata la spitalul Judetean Galati, m&amp;acirc;ine o externeaza pentru a putea pleca spre Iași. Va rog sa o ajutați.&lt;/p&gt;\r\n&lt;p&gt;&amp;Icirc;și creste copilul de c&amp;acirc;nd l-a născut singura, este pensionat pe caz boala.&lt;/p&gt;\r\n&lt;p&gt;Are urgent nevoie pentru a ajunge la Iași unde poate beneficia de tratament specific toate resursele pe care le-a avut s-au cheltuit &amp;icirc;n scop diagnostic: analize, drumuri, CT-uri o alta operație laparoscopica.&lt;/p&gt;','','da','','asistati-social/Ivanciu-Loredana-Daniela/Copie-CI-Invanciuc-Daniela-Loranda.jpg','+40 742 823 463'),(79,'Dumitru','Ionela','2820226170108','ZL297508','Str. Luca Arbore nr. 42','Sat Braniștea (Com. Braniștea)','Galați','Necăsătorită',7,'&lt;p&gt;Trăiește &amp;icirc;n concubinaj cu Andrei Sebastian. Au 7 copiii &amp;icirc;mpreună, dintre care unui bolnav de cancer, și trăiesc doar din veniturile tatălui și alocațiile de stat.&lt;/p&gt;\r\n&lt;p&gt;Iată numele copiilor:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Atanasiu Constanta Casandra&lt;/li&gt;\r\n&lt;li&gt;Atanasiu Adrian Ștefan&lt;/li&gt;\r\n&lt;li&gt;Andrei Florin Iulian&lt;/li&gt;\r\n&lt;li&gt;Andrei Angellina Denisa&lt;/li&gt;\r\n&lt;li&gt;Andrei Mihaela Mădălina&lt;/li&gt;\r\n&lt;li&gt;Andrei Mihăiță Robert&lt;/li&gt;\r\n&lt;/ul&gt;','','da','','asistati-social/Dumitru-Ionela/Dumitru-Ionela.jpg','0729466126'),(80,'Angheluță','Mihaela-Romină','2971128170036','ZL519167','Str. Vasile Lupu nr. 8','Sat Braniștea (Com. Braniștea)','Galați','Necăsătorită',2,'&lt;p&gt;Locuiește &amp;icirc;n concubinaj cu Oglindă Marian și au 2 copii. Nu au venituri, trăiesc doar din alocațiile de stat pentru copii.&lt;/p&gt;','','da','','asistati-social/Angheluta-Mihaela-Romina/Angheluta-Mihaela-Romina.jpg',''),(81,'Stoian','Angelica','2900912330545','ZL346846','Str. Grigore Ghica Voievod nr. 12','Sat Braniștea (Com. Braniștea)','Galați','Căsătorită',2,'&lt;p&gt;Familia Stoia Tudorel și Angelica au 2 copii elevi și nu au venituri dec&amp;acirc;t alocațiile de staat pentr&lt;/p&gt;','','da','','asistati-social/Stoian-Angelica/Stoian-Angelica.jpg',''),(82,'Radu','Angelica','2710120463017','IF800021','Sat Căciulați, Com. Moara Vlăsiei, Str. Academiei nr. 4','Sat Căciulați','Ilfov','Căsătorită',0,'&lt;p&gt;Suflet de mamă! Angelica &amp;icirc;și crește singură cei 2 copii &amp;icirc;ntr-o sărăcie lucie.&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Soțul a bătut-o p&amp;acirc;nă i-a sf&amp;acirc;r&amp;acirc;mat oasele, iar apoi a părăsit-o pentru că a născut un copil cu probleme de sănătate. &amp;Icirc;n tot acest chin, &amp;icirc;n loc să &amp;icirc;și blesteme soarta, Angelica a ales să adopte o fetiță (nepoata ei, care &amp;icirc;nsă a fost abandonată de mamă la 14 zile de viață) și să o crească singură. Cei 3 trăiesc de azi pe m&amp;acirc;ine &amp;icirc;n satul Odăieni, unde &amp;icirc;nchiriază o cameră, dintr-o casă &amp;icirc;ngenunchiată de vreme. &amp;Icirc;nsă sunt nevoiți să părăsească acestă locuință &amp;icirc;n 2 luni.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Singură cu toate, dobor&amp;acirc;tă de griji și necazuri, a găsit puterea să meargă &amp;icirc;nainte. &amp;Icirc;mpreună cu ajutorul oamenilor a reușit să cumpere o bucată de păm&amp;acirc;nt, pe care a pus temelia unei mici căsuțe de 28 mp, &amp;icirc;nsă nu mai deține resursele financiare necesare să o construiască. Pentru un venit suplimentar d-na Angelica merge cu ziua la vecini la munca c&amp;acirc;mpului, &amp;icirc;nsă nu este suficient pentru a face față tuturor nevoilor, &amp;icirc;n special medicamentele băiatului. Visul familiei &amp;icirc;n fața acestui destin crunt este să aibă o căsuță foarte modestă, chiar și fără electricitate, doar să aibă un acoperiș deasupra capului.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;','','nu','','asistati-social/Radu-Angelica/Copie CI-Angelica-Radu.jpg','+40725491426'),(83,'Ciobotaru','Mariana','2900612295024','ZL341436','Str. Drumul de Centură nr. 39P bl. M13, ap. 15','Galați','Galați','Căsătorită',2,'&lt;p&gt;Doamna Mariana are probleme de sănătate și &amp;icirc;n ultimul an (2023-2024) medicii n-au reușit să afle ce are. Acum i s-a spus că are un nodul la splină și i s-a recomandat o internare la oncologie.&lt;/p&gt;','','da','','asistati-social/Ciobotaru-Mariana/Ciobotaru-Mariana-copie-bi.jpg','+40761948628'),(84,'Mitrof','Ioana','2810512170032','ZL574161','ZL574161 2810512170032 Str. Bahluiului nr. 2, bl. L10, sc.2, et.7, ap. 51','Galați','Galați','Divorțată',2,'&lt;p&gt;Ioana Mitrof suferă de cancer la s&amp;acirc;n.&lt;/p&gt;\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;','','da','','asistati-social/Mitrof-Ioana/Ioana-Mitrof-copie-CI.jpg','+40 720 622 704'),(85,'Safta','Nicoleta','2880915090120','RZ321484','Aleea Mizil nr. 2, bl. 2, et. 4, ap. 403','București','București','Necăsătorită',0,'&lt;p&gt;Copil orfan crescut la Valea Plopului la centrul Părintelui Nicolae Tănase.&lt;/p&gt;\r\n&lt;p&gt;Are epilepsie și lucrează 4 ore pe zi la Carrefour &amp;icirc;n București.&lt;/p&gt;\r\n&lt;p&gt;Are nevoie de ajutor pentru medicamente.&lt;/p&gt;','','da','','asistati-social/Safta-Nicoleta/CI-Nicoleta-Safta.jpg','40 758 933 848'),(86,'Tița','Alin-Ionuț','1820617033345','AZ484357','Sat Dobrotu nr. 140, comuna Albeștii de Argeș,','Sat Dobrotu','Argeș','Căsătorit',4,'&lt;p&gt;Alin si Adelina, ii stii, cei cu 4 copii, cu care sunt foarte aproapiata au o situatie delicata, trebuie sa se mute din chiria actuala in alta, au o gramada de credite, urmeaza si botezul copilului cel mic si sunt fortati sa schimbe chiria. Au gasit ceva cu 550 dar cere 2 luni garantie. Au cumva nevoie de 1500 euro ca sa se mute.&lt;/p&gt;\r\n&lt;p&gt;I-am sugerat Adelinei sa vorbim cu tine, poate punem mana de la mana si ii ajutam , dar nu vrea, probabil ii este rusine sau n-am idee. Nici n a vrut sa auda, daca as fi avut, le as fi dat eu, dar n-am.&lt;/p&gt;\r\n&lt;p&gt;Vreau sa fac ceva pentru ei si singurul lucru la care ma gandesc e sa vorbim unii cu ceilalti fara sa facem o postare si sa ii dam cadou. In acelasi timp imi e frica sa nu se supere pe mine daca afla ca am apelat la tine.&lt;br /&gt;Ce crezi ca ar trebui facut?&lt;/p&gt;','','da','','asistati-social/Tita-Alin-Ionut/Tita-Alin-Ionut-ci.jpg','+40 730 879 470'),(87,'Nica','Maria','2570515323936','SB738688','Str. Semaforului nr. 14, sc. D, et. 3, ap. 53','Sibiu','Sibiu','Căsătorită',0,'&lt;p&gt;Doamna Maria are cancer mamar și are nevoie de bani pentru tratamente medicale.&lt;/p&gt;\r\n&lt;p&gt;A vorbit cu 5 firme care să-i facă donație impozitul pe venit.&lt;/p&gt;\r\n&lt;div data-pm-slice=&quot;1 1 []&quot; data-en-clipboard=&quot;true&quot;&gt;&lt;strong&gt;CIP UTIL TRANS SRL (Sibiu)&lt;/strong&gt; - 296 lei&lt;/div&gt;\r\n&lt;div&gt;&lt;strong&gt;Infiniti Com SRL&lt;/strong&gt; &lt;strong&gt;(Sibiu)&lt;/strong&gt; - 891 lei&lt;/div&gt;\r\n&lt;div&gt;&lt;strong&gt;SELF TRICONF SRL (Sibiu)&lt;/strong&gt; - 620 lei&lt;/div&gt;\r\n&lt;div&gt;&lt;strong&gt;VALDY GLASS &amp;nbsp;SRL (Sibiu)&lt;/strong&gt; -&lt;strong&gt; &lt;/strong&gt;358 lei&lt;/div&gt;\r\n&lt;div&gt;&lt;strong&gt;VIOLA&amp;nbsp; SRL (Sibiu)&lt;/strong&gt; - 4955 lei&lt;/div&gt;\r\n&lt;div&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;div&gt;Primite &amp;icirc;n contul asociației&lt;/div&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;\r\n&lt;div&gt;1 iul. 2024 - Trezoreria Municipiul Sibiu - 1807 lei&lt;/div&gt;\r\n&lt;/li&gt;\r\n&lt;li&gt;\r\n&lt;div&gt;5 dec. 2024 - Trezoreria Municipiul Sibiu - 3268 lei&lt;/div&gt;\r\n&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;div&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;div&gt;Total: 5075 lei&lt;/div&gt;\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;','','da','','asistati-social/Nica-Maria/Maria-Nica-CI.jpg','+40 771 536 016'),(88,'Sefer','Tatiana-Mariana','2680426170320','ZL489431','Sat Fârțănești (com. Fârțănești)','','','Căsătorită',4,'&lt;p&gt;Locuiește cu soțul ei &amp;icirc;ntr-o casă &amp;icirc;n cartierul Filești (jud. Galați) &amp;icirc;ntr-o casă improvizată fără utilități. Are 4 copii mari. Este șomeră. Se &amp;icirc;ngrijește de soțul ei care are cancer la g&amp;acirc;t. Soțului i s-a desfăcut contractul de muncă &amp;icirc;n 2024 din cauza bolii. Acum (2025) nu au venituri și se chinuie să trăiască de pe azi pe m&amp;acirc;ine.&lt;/p&gt;','','da','','asistati-social/Sefer-Tatiana-Mariana/Tatiana-Sefer.jpg','0784342672'),(89,'Iovan','Cornelia','2751120441514','RX804688','Ale. Terasei nr.1, bl. D1, sc.2, et.1, ap.20','București','București','Căsătorită',0,'&lt;p&gt;Doamna Cornelia Iovan suferă de &lt;strong data-start=&quot;396&quot; data-end=&quot;468&quot;&gt;cancer mamar invaziv, hormono-dependent (HR-pozitiv) și HER2-negativ&lt;/strong&gt;, aflat &amp;icirc;ntr-un stadiu precoce cu afectare ganglionară limitată.&lt;/p&gt;','','da','','asistati-social/Iovan-Cornelia/ci-iovan-cornelia.jpg',''),(90,'Munteanu','Iulian','1840105170025','ZL163814','Str. Basarabiei nr. 125m bl. i6A, sc. 1, et. 3, ap. 14','Galați','Galați','Căsătorit',3,'&lt;p&gt;Iulian Munteanu este fost membru ASCOR Galați. Este căsătorit și are 3 copilași. Soția nu muncește. El este angajat la Șantierul Navel DAMEN Galați. Se descurcă greu cu banii trebuind să &amp;icirc;ntrețină toată familia.&lt;/p&gt;','','da','','asistati-social/Munteanu-Iulian/ci-Iulian-Munteanu.jpg','+40762523046');
