INSERT INTO `contracte` VALUES (1,'AOT12025','<p class=\"MsoNormal\">&Icirc;NCHIEIAT &Icirc;NTRE:</p>\r\n<p class=\"MsoNormal\"><strong>1. Sponsor:</strong><br />Denumire: GEOMETRICS ENERGY S.R.L.<br />Sediul: București, sector 1, str. Radu Popescu nr. 17, bl. 24A, sc. 2, et. 6, ap. 62<br />CUI: RO34897122<br />Nr. Reg. Comerțului: J40/10129/2015<br />Reprezentată legal prin: RAGEA FLORIN ALEXANDRU, &icirc;n calitate de Administrator,<br />denumită &icirc;n continuare \"Sponsor\".</p>\r\n<p class=\"MsoNormal\"><strong>2. Beneficiar:</strong><br />Denumire: ASOCIAȚIA ORTODOXIA TINERILOR<br />Sediul: Galați, str. Frunzei nr. 5, bl. F3, sc. 2, et. 8, ap. 63, cod poștal 800684, jud. Galați<br />CUI: 30116644<br />Nr. &icirc;nreg. &icirc;n Registrul asociațiilor și fundațiilor: DS1755/233/2012<br />Cont bancar (IBAN): RO71 UGBI 00007020 0130 8 RON<br />Reprezentată legal prin: BALAN CLAUDIU, &icirc;n calitate de Președinte,<br />denumită &icirc;n continuare \"Beneficiar\".</p>\r\n<p class=\"MsoNormal\"><strong>Art. 1 &ndash; Obiectul contractului</strong></p>\r\n<p class=\"MsoNormal\">Sponsorul acordă Beneficiarului o sponsorizare &icirc;n valoare de 15.508 lei, &icirc;n baza prevederilor Legii nr. 32/1994 privind sponsorizarea și ale art. 25 alin. (4) lit. i) din Legea nr. 227/2015 privind Codul Fiscal.</p>\r\n<p class=\"MsoNormal\"><strong>Art. 2 &ndash; Destinația sponsorizării</strong></p>\r\n<p class=\"MsoNormal\">Suma sponsorizată va fi utilizată de către Beneficiar exclusiv pentru activitățile prevăzute &icirc;n statutul său, respectiv desfășurarea de activități filnatropoce, educaționale, culturale și religioase.</p>\r\n<p class=\"MsoNormal\"><strong>Art. 3 &ndash; Modalitatea de plată</strong></p>\r\n<p class=\"MsoNormal\">Sponsorizarea se va realiza prin completarea și depunerea de către Sponsor a Declarației 177 la ANAF, urm&acirc;nd ca ANAF să vireze suma &icirc;n contul Beneficiarului.</p>\r\n<p class=\"MsoNormal\"><strong>Art. 4 &ndash; Obligații Beneficiar</strong></p>\r\n<p class=\"MsoNormal\">Beneficiarul se obligă:<br />a) să utilizeze suma sponsorizată conform destinației menționate;<br />b) să pună la dispoziția Sponsorului, la cerere, documente justificative privind utilizarea fondurilor;<br />c) să respecte obligațiile de raportare prevăzute de lege (Legea 32/1994, Codul Fiscal).</p>\r\n<p class=\"MsoNormal\"><strong>Art. 5 &ndash; Obligații Sponsor</strong></p>\r\n<p class=\"MsoNormal\">Sponsorul se obligă:<br />a) să completeze contractul &icirc;n conformitate cu prevederile legale;<br />b) să depună Declarația 177 &icirc;n termenul legal.</p>\r\n<p class=\"MsoNormal\"><strong>Art. 6 &ndash; Durata contractului</strong></p>\r\n<p class=\"MsoNormal\">Prezentul contract intră &icirc;n vigoare la data semnării de către ambele părți și este valabil p&acirc;nă la &icirc;ndeplinirea tuturor obligațiilor contractuale.</p>\r\n<p class=\"MsoNormal\"><strong>Art. 7 &ndash; Alte clauze</strong></p>\r\n<p class=\"MsoNormal\">Orice modificare a prezentului contract se va face prin act adițional semnat de ambele părți.<br />Prezentul contract a fost &icirc;ncheiat &icirc;n 2 exemplare originale, c&acirc;te unul pentru fiecare parte.</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-ignore: vglayout; position: absolute; z-index: 251658240; margin-left: 102px; margin-top: 82px; width: 88px; height: 60px;\"><br /></span><br />Sponsor,<br />GEOMETRICS ENERGY S.R.L.<br />Reprezentant: RAGEA FLORIN ALEXANDRU<br />Semnătură: _________________</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-ignore: vglayout; position: absolute; z-index: 251659264; margin-left: 110px; margin-top: 93px; width: 91px; height: 138px;\"><br /></span><br />Beneficiar,<br />ASOCIAȚIA ORTODOXIA TINERILOR<br />Reprezentant: BALAN CLAUDIU<br />Semnătură: _________________</p>','GEOMETRICS ENERGY S.R.L.','ASOCIAȚIA ORTODOXIA TINERILOR','15508','2025-04-08','contracte/2025/contract_68288116d9a9a3.76490470.pdf'),(2,'AOT22025','<p><strong>&Icirc;NCHIEIAT &Icirc;NTRE:</strong></p>\r\n<p>1. Sponsor: Denumire: WEB DOTS S.R.L. Sediul: BUCURESTI sect. 4 str. VISANA nr. 5 bl. 43 sc. A et. 1 ap. 8 CUI: RO23094098 Nr. Reg. Comerțului: J40/783/2008 Reprezentată legal prin: Vaduva Mihai-Stefan, &icirc;n calitate de Administrator, denumită &icirc;n continuare \"Sponsor\".</p>\r\n<p>2. Beneficiar: Denumire: ASOCIAȚIA ORTODOXIA TINERILOR Sediul: Galați, str. Frunzei nr. 5, bl. F3, sc. 2, et. 8, ap. 63, cod poștal 800684, jud. Galați CUI: 30116644 Nr. &icirc;nreg. &icirc;n Registrul asociațiilor și fundațiilor: DS1755/233/2012 Cont bancar (IBAN): RO71 UGBI 00007020 0130 8 RON Reprezentată legal prin: BALAN CLAUDIU, &icirc;n calitate de Președinte, denumită &icirc;n continuare \"Beneficiar\".</p>\r\n<p><strong>Art. 1 &ndash; Obiectul contractului</strong><br />Sponsorul acordă Beneficiarului o sponsorizare &icirc;n valoare de <strong>3.539,00 lei,</strong> &icirc;n baza prevederilor Legii nr. 32/1994 privind sponsorizarea și ale art. 25 alin. (4) lit. i) din Legea nr. 227/2015 privind Codul Fiscal.</p>\r\n<p><strong>Art. 2 &ndash; Destinația sponsorizării</strong><br />Suma sponsorizată va fi utilizată de către Beneficiar exclusiv pentru activitățile prevăzute &icirc;n statutul său, respectiv promovarea credinței și spiritualității creștin-ortodoxe &icirc;n r&acirc;ndul tinerilor, precum și oferirea de sprijin material și spiritual persoanelor aflate &icirc;n dificultate .</p>\r\n<p><strong>Art. 3 &ndash; Modalitatea de plată</strong><br />Sponsorizarea se va realiza prin completarea și depunerea de către Sponsor a Declarației 177 la ANAF, urm&acirc;nd ca ANAF să vireze suma &icirc;n contul Beneficiarului.</p>\r\n<p><strong>Art. 4 &ndash; Obligații Beneficiar</strong><br />Beneficiarul se obligă: a) să utilizeze suma sponsorizată conform destinației menționate;<br />b) să pună la dispoziția Sponsorului, la cerere, documente justificative privind utilizarea<br />fondurilor;<br />c) să respecte obligațiile de raportare prevăzute de lege (Legea 32/1994, Codul Fiscal).</p>\r\n<p><strong>Art. 5 &ndash; Obligații Sponsor</strong><br />Sponsorul se obligă:<br />a) să completeze contractul &icirc;n conformitate cu prevederile legale;<br />b) să depună Declarația 177 &icirc;n termenul legal.</p>\r\n<p><strong>Art. 6 &ndash; Durata contractului</strong><br />Prezentul contract intră &icirc;n vigoare la data semnării de către ambele părți și este valabil p&acirc;nă<br />la &icirc;ndeplinirea tuturor obligațiilor contractuale.</p>\r\n<p><strong>Art. 7 &ndash; Alte clauze</strong><br />Orice modificare a prezentului contract se va face prin act adițional semnat de ambele<br />părți.<br />Prezentul contract a fost &icirc;ncheiat &icirc;n 2 exemplare originale, c&acirc;te unul pentru fiecare parte.</p>','WEB DOTS S.R.L.','ASOCIAȚIA ORTODOXIA TINERILOR','3.539','2025-05-09','contracte/2025/contract_6828810d430e49.62978849.pdf'),(3,'AOT32025','<p><!-- [if !mso]>\r\n<style>\r\nv\\:* {behavior:url(#default#VML);}\r\no\\:* {behavior:url(#default#VML);}\r\nw\\:* {behavior:url(#default#VML);}\r\n.shape {behavior:url(#default#VML);}\r\n</style>\r\n<![endif]--><!-- [if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:TrackMoves>false</w:TrackMoves>\r\n  <w:TrackFormatting/>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:DoNotPromoteQF/>\r\n  <w:LidThemeOther>EN-US</w:LidThemeOther>\r\n  <w:LidThemeAsian>X-NONE</w:LidThemeAsian>\r\n  <w:LidThemeComplexScript>X-NONE</w:LidThemeComplexScript>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n   <w:SplitPgBreakAndParaMark/>\r\n   <w:EnableOpenTypeKerning/>\r\n   <w:DontFlipMirrorIndents/>\r\n   <w:OverrideTableSt