INSERT INTO `pelerinaje` VALUES (1,'Pelerinaj în Israel (7-12 martie 2026)','Israel','2026-03-07','2026-03-12','<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Iată programul complet al pelerinajului:</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span id=\"more-12738\" style=\"box-sizing: border-box; margin: 0px; padding: 0px;\"></span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Ziua 1, s&acirc;mbătă 7 martie 2026 &ndash; București &ndash; Tel-Aviv (HiSky)</span></span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">&Icirc;nt&acirc;lnire cu &icirc;nsoțitorul de grup &icirc;n Aeroportul București OTOPENI la&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">ora 17.45&nbsp;</span>pentru zbor București-Tel-Aviv cu&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">compania HiSky</span>. Decolare la&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">ora 20,00 din București,</span>&nbsp;aterizare pe aeroportul Ben Gurion din&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Tel-Aviv la ora 22.30.&nbsp;</span>Cazare la hotel in Bethleem.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Ziua 2, duminică 8 martie 2026 &ndash; Hozeva &ndash; R&acirc;ul Iordan &ndash; Marea Moartă &ndash; Ierihon</span></span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Dimineața luăm micul dejun. Vom merge către pustiul<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Hozeva&nbsp;</span>unde vom vizita&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Mănăstirea Sf. Gheorghe.</span>&nbsp; &Icirc;n mănăstire sunt adăpostite moaștele&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Sf. Ioan Ioacob Hozevitul&nbsp;</span>(sf&acirc;nt rom&acirc;n născut &icirc;n zona Botoșanului) și tot aici se află şi peştera unde a trăit mulţi ani&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Proorocul Ilie</span>.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Cobor&acirc;m pe valea Iordanului și oprim la&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">locul botezului lui Iisus.&nbsp;</span>Aici vom primi binecuv&acirc;ntarea &icirc;n apele&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">r&acirc;ului Iordan.&nbsp;</span>Vom merge să vedem&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Marea Moartă</span>, unde vom face un scurt dar relaxant.&nbsp;&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Marea Moartă</span>&nbsp; este lipsită de viață și este situată la -420 m. sub oceanul planetar. Cine&nbsp; dorește poate experimenta și o baie &icirc;n marea cu cea mai ridicată salinitate din lume.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Plecăm spre Ierihon, cel mai vechi oraș din lume unde vom vizita&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Dudul lui Zaheu</span>&nbsp;apoi ne &icirc;ndreptăm către Muntele Ispitirii pentru a avea o privire panoramică asupra&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Mănăstirii Carantania</span>&nbsp;de pe&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Muntele Ispitirii</span>. Apoi vizităm&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Așezăm&acirc;ntul Rom&acirc;nesc de la Ierihon</span>. L&acirc;ngă r&acirc;ul Iordan este&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Mănăstirea Sf. Gherasim</span>.&nbsp; Aici avem ocazia să aflăm ceea ce spune tradiția despre viețuirea Sf.&nbsp; Gherasim de la Iordan alături de leul său.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Cazare si cina la hotel &icirc;n Bethleem.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Ziua 3, luni 9 martie 2026 &ndash; Ierusalim, Muntele Măslinilor &ndash; Via Dolorosa</span></span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Mic dejun. Ne &icirc;ndreptăm spre Ierusalim, numit și Orașul Păcii, unde pe Muntele Măslinilor, unde vom vizita:<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Mănăstirea Ortodoxă a &Icirc;nălţării Domnului&nbsp;</span>ce&nbsp; amintește de &Icirc;nălțarea Domnului la cer și unde ne &icirc;nchinăm la locul&nbsp; unde a fost găsit pentru a doua oară capul Sf. Ioan Botezătorul;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Mănăstirea Pater Noster</span>, loc unde potrivit tradiției Iisus i-a &icirc;nvăţat pe ucenicii Săi Rugăciunea Domnească &bdquo;Tatăl nostru&rdquo;;&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Mănăstirea &bdquo;Dominus Flevit&rdquo;&nbsp;</span>(&bdquo;Domnul&nbsp; a pl&acirc;ns&rdquo;) zidită &icirc;n formă de lacrimă, pe locul unde M&acirc;ntuitorul Iisus&nbsp; Hristos a pl&acirc;ns lipsa credință a celor din Cetatea Sf&acirc;ntă dar a depl&acirc;ns&nbsp; și soarta pe care o va avea Ierusalimul;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Biserica Sf&acirc;nta Maria Magdalena&nbsp;</span>unde se află moaștele &icirc;ntregi ale Sfintei Mucenițe și Prințese Elisabeta Feodorovna a Rusei și a Sfintei Varvara, ucenica ei;&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Grădina Ghetsimani&nbsp;</span>cu&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Naţiunilor</span>&nbsp;ridicată pe locul &icirc;n care M&acirc;ntuitorul s-a rugat &icirc;nainte de a fie prins;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Biserica Morm&acirc;ntul Maicii Domnului&nbsp;</span>ce adăpostește Morm&acirc;ntul Fecioarei Maria şi&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Grota Trădării,&nbsp;</span>grota unde a fost &icirc;nchis Iisus &icirc;nainte de judecată.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Intrăm &icirc;n Cetatea Sf&acirc;ntă a Ierusalimului pe&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Poarta &Icirc;nt&acirc;iului Mucenic Ştefan</span>&nbsp;şi parcurgem pe jos&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Via Dolorosa</span>&nbsp;(Calea Crucii), cu cele 14 opriri ale M&acirc;ntuitorului Iisus Hristos, ajung&acirc;nd la&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Sf. &Icirc;nvieri&nbsp;</span>&icirc;n care vom vizita toate locurile sfinte:<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Golgota</span>,<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Piatra Ungerii</span>,<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Sf. Morm&acirc;nt, locul unde s-a aflat Sf. Cruce,&nbsp;</span>etc).&nbsp; Apoi vizităm&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Zidul Pl&acirc;ngerii</span>&nbsp;și&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Foișorul Cinei celei de taina</span>&nbsp;de pe Sion.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Luăm cina la hotel in Bethleem și apoi ne odihnim 2-3 ore.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Dăcă autoritățile ne permit, seara la ora 23.30 plecăm spre Ierusalim la&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Sf&acirc;ntului Morm&acirc;nt</span>&nbsp;să participăm la&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Sf&acirc;nta Liturghie.&nbsp;</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Ziua 4,&nbsp; marți 10 martie 2026 &ndash; Mănăstirea Sf. Sava, Bethleem, Biserica Nașterii</span></span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Ne &icirc;ntoarcem din Ierusalim. Ora 04.00 &ndash; Ne culcăm.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">08.30&nbsp; &ndash; Mic dejun</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">După micul dejun mergem &icirc;n pustiul Iudeii pentru a vizita&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Mănăstirea Sf. Teodosie</span>&nbsp; unde este Peştera Magilor &icirc;n care se află mormintele Sf. Teodosie, Sf.&nbsp; Sofia &ndash; mama Sf. Sava, Sf. Evloghia &ndash; mama Sf. Teodosie, Sf. Teodota &ndash;&nbsp; mama Sf. Cosma şi Damian. De la Mănăstirea Sf. Teodosie ne vom deplasa&nbsp;către<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Mănăstirea Sf. Sava</span>, mănăstirea care datează din sec. V și care adăpostește moaştele Sf. Sava (<em style=\"box-sizing: border-box; margin: 0px; padding: 0px;\">accesul&nbsp; &icirc;n incinta mănăstirii este permis numai domnilor, doamnele pot merge la&nbsp; Turnul Femeii, de unde se poate vedea mănăstirea şi locul unde s-a&nbsp; nevoit Sf. Sava</em>).</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Revenim &icirc;n Bethleem pentru a vizita&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica C&acirc;mpul Păstorilor</span>, locul unde erau păstorii, &icirc;n noaptea &icirc;n care s-a născut Pruncul Iisus Hristos. Continuăm cu&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Ortodoxă a Naşterii Domnului</span>,&nbsp; ce adăposteşte Peştera &icirc;n care s-a născut Domnul Iisus Hristos şi&nbsp; icoana făcătoare de minuni a Maicii Domnului numită &ldquo;Betleemița&rdquo; sau&nbsp; &ldquo;Apărătoarea Bethleemului&rdquo;). La mică distanță se află&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Grota Laptelui</span>,&nbsp; unde, potrivit tradiţiei s-a oprit Maica Domnului cu Pruncul, &icirc;n&nbsp; noaptea &icirc;n care Dreptul Iosif a primit poruncă de la &icirc;nger să fugă &icirc;n&nbsp; Egipt.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Ziua 5, miercuri 11 martie 2026 &ndash; Muntele Tabor &ndash; Nazareth &ndash; Capernaum</span></span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Mic dejun. Ne &icirc;ndreptăm spre orașul care este descris ca fiind locul unde a copilărit Iisus Hristos &ndash;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Nazareth</span>. Aici vom vizita&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Ortodoxă Sf. Gavriil</span>,&nbsp; ridicată deasupra izvorului considerat a fi cel al Fecioarei Maria și&nbsp; aflat &icirc;n apropierea casei acesteia din Nazaret. Biserica a fost pictată&nbsp; de frații Moroșanu &icirc;n 1977.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Ne &icirc;ndreptăm spre&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Muntele Tabor</span>&nbsp;unde vom urca cu taxiurile la Biserica ce aduce aminte de&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Schimbarea la Faţă a Domnului; vizităm biserica greco-ortodoxă unde se află icoana făcătoare de minuni a Maicii Domnului.</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Continuăm cu biserica din&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Cana din Galileii</span>. Aici a avut loc prima minune a lui Iisus, prefacerea apei &icirc;n vin la nunta din Cana Galileii.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Apoi vom face o&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">plimbare pe Marea Galilei</span>, cu o barcă ce amintește de corăbiile din timpul M&acirc;ntuitorului.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Vom merge către oraşul cel mai iubit de către M&acirc;ntuitorul &ndash;&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Capernaum</span>, unde a săv&acirc;rșit cele mai multe minuni. Aici vom merge la&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Sf. Petru</span>, ce aduce aminte de repunerea &icirc;n apostolat a lui Petru. De aici vom merge pe&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Muntele Fericirilor</span>&nbsp; unde vom vizita biserica octogonală ce fost ridicată pe locul unde&nbsp; M&acirc;ntuitorul a ținut predica despre Legea cea Nouă, rostind cele 9&nbsp; fericiri.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Cazare si cina la hotel in Nazaret sau Tiberias</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Ziua 6, joi, 12 martie 2026 &ndash; Haifa &ndash; Caesarea &ndash; Tel-Aviv</span></span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Micul dejun.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Deplasare &icirc;n Ierusalim pe&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Muntele Sionului</span>&nbsp;&ndash; ne vom &icirc;nchina &icirc;n&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Biserica Adormirii Maicii Domnului</span>, apoi vizităm&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Foişorul &bdquo;Cina cea de Taină&rdquo;&nbsp;</span>şi&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Morm&acirc;ntul Sf&acirc;ntului Prooroc şi Psalmist David</span>. Apoi mergem să vedem&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Zidul Pl&acirc;ngerii și&nbsp;</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Așezăm&acirc;ntul Rom&acirc;nesc de la Ierusalim.&nbsp;</span>Dacă ne mai răm&acirc;ne timp vom face un tur panoramic al orașului Tel-Aviv</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Seara, ajungem la Aeroportul Ben Gurion din Tel-Aviv.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\">Decolare din<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;Tel-Aviv la ora 23,30</span>&nbsp;aterizare &icirc;n<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">&nbsp;București la ora 02,00</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Număr de locuri:</span>&nbsp;32</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Pret:&nbsp;</span></span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">510 $ + 430 &euro;&nbsp;</span>(adică aproximativ&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">875 de euro.</span></span>&nbsp;Depinde de evoluția dolarului).</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 1rem; padding: 0px; color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', \'Noto Sans\', \'Liberation Sans\', Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 16px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Plata se face separat: 510 $ plătiți &icirc;n dolari și 430 &euro;&nbsp; plătiți &icirc;n euro.&nbsp;</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #000000;\"><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; font-weight: bolder;\">Avansul minim este de&nbsp;<span style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #ff0000;\">250 de euro</span>&nbsp;de persoană.</span></span></span></p>','https://ortodoxiatinerilor.ro/pelerinaj-in-israel-5-10-martie-2026/',510.00,430.00,'activ','2026-02-23 13:43:50');
