INSERT INTO `tabere` VALUES (9,'Tabără de toamnă la Sâmbăta de Sus, județul Brașov (2 - 5 noiembrie 2012) ','Sâmbăta de Sus','Brașov','România',37,'0000-00-00','0000-00-00','Ziua 1:  \"Iubirea de neam şi ţară. Curajul şi bărbăţia românului credincios. (Sfinţii Martiri Brâncoveni).\" Prezintă: Dănuț Nancu – licențiat în istorie / jurist.\r\nZiua 2: \"Părintele Arsenie Boca şi Rezistenţa anticomunista din Munţii Făgăraşului\". Prezintă Ioana Hașu – jurnalist, moderator și realizator de emisiuni radiofonice.\r\nZiua 3: \"Sfânta Scriptură - spațiu de întâlnire zilnică a omului cu Dumnezeu\". Prezintă Gheorghe Butuc – doctorand în teologie, profesor la Seminarul Teologic din Galați.','https://ortodoxiatinerilor.ro/anunturi-tabere/3168-tabara-sambata-de-sus-2012','https://ortodoxiatinerilor.ro/tabere-ortodoxe/19029-impresii-fotografii-tabara-sambata-de-sus','https://ortodoxiatinerilor.ro/images/stories/2012/09/tabara-de-toamn-academia-sambata-de-sus.jpg',220,'da','Academia Sâmbăta de Sus','da','Dănuț Nancu – licențiat în istorie / jurist.\r\nIoana Hașu – jurnalist, cercetător CNSAS\r\nGheorghe Butuc - profesor teologie\r\n'),(8,'Prima tabără de vară a Asociației Ortodoxia Tinerilor va avea loc la Putna ','Putna','Suceava','România',28,'2012-08-17','2012-08-20','Seara 1: Prezentarea Asociaţiei Ortodoxia Tinerilor şi a proiectelor noastre.\r\nSeara 2: Familia ortodoxă: soluţia la toate problemele lumii\r\nSeara 3: Sexualitatea umană în perspectiva Bisericii Ortodoxe. Cercul vicios al indecenței.\r\n','https://ortodoxiatinerilor.ro/anunturi-tabere/18863-prima-tabara-de-vara-aot','https://ortodoxiatinerilor.ro/tabere-ortodoxe/18912-fotografii-impresii-tabara-putna','https://ortodoxiatinerilor.ro/images/stories/2012/07/manastirea-putna-vedere-de-ansamblu.jpg',145,'da','Pensiunea Mădălina','da','Dan Tudorache, istoric, fondatorul site-ului fericiticeiprigoniti.net'),(7,'Tabără în cinstea zilei naționale a României și a Sfântului Apostol Andrei – ocrotitorul românilor la Alba-Iulia','Oașa','Alba','România',40,'2012-11-29','2012-12-02','','https://ortodoxiatinerilor.ro/anunturi-tabere/19051-tabara-alba-iulia','https://ortodoxiatinerilor.ro/tabere-ortodoxe/19098-tabara-ziua-nationala-2012','https://ortodoxiatinerilor.ro/images/stories/2012/11/catedrala-alba-iulia.jpg',0,'da','Mănăstire Oașa și Schitul Găbud','da',''),(10,'Tabără de iarnă la Bușteni','Bușteni','Prahova','România',22,'2013-02-13','2013-02-17','Seara 1: „Premizele unei căsătorii fericite și ale unei familii care să-i ducă pe soți pe drumul mântuirii.”\r\nSeara 2: „Căsătoria ca stare permanentă de jertfă și nicidecum ca o viață în puf, plină de plăceri. Diferența majoră între iubirea cu iz comercial și iubirea jertfelnică pe care ne-o cere Dumnezeu.”\r\nSeara 3: „Cum pot trăi soțul și soția o viață întreagă fără a folosi mijloace contraceptive în relațiilor lor. Este reală perspectivă Bisericii Ortodoxe de a cere creștinilor o familie care să se lase cu totul în voia lui Dumnezeu?”\r\nSeara 4: „De ce astăzi tinerii se căsătoresc târziu sau nu se mai căsătoresc deloc.”','https://ortodoxiatinerilor.ro/anunturi-tabere/19163-tabara-iarna-sinaia-2013','https://ortodoxiatinerilor.ro/tabere-ortodoxe/19253-tabara-busteni-asociatia-ortodoxia-tinerilor-februarie-2013','https://ortodoxiatinerilor.ro/images/stories/2013/01/tabara-lasinaia-2013.jpg',180,'da','Vila Iulia și Vila Gabi','nu','profesor dr. Gheorghe Butuc');
/*!40000 ALTER TABLE `tabere` ENABLE KEYS */;
UNLOCK TABLES;

